UPDATE BSYCDGP CDGP
   SET DEL_YN = 'Y', USE_YN = 'N', MOD_DT = CURRENT_TIMESTAMP, MOD_BY = #{MOD_BY}
 WHERE CDGP.CODE_GROUP_ID = #{CODE_GROUP_ID}
   AND CDGP.DEL_YN = 'N'

