SELECT FROM BSYCMCD CMCD WHERE CMCD.DEL_YN = 'N'
AND CMCD.CODE_GROUP_ID = #{CODE_GROUP_ID}
AND (UPPER(CMCD.CODE) LIKE CONCAT('%', UPPER(#{CODE_NAME}), '%') OR UPPER(CMCD.CODE_NAME) LIKE CONCAT('%', UPPER(#{CODE_NAME}), '%'))
AND CMCD.USE_YN = #{USE_YN}
ORDER BY CMCD.CODE_GROUP_ID, CMCD.SORT_ORDER, CMCD.CODE

SELECT COUNT(*) FROM BSYCMCD CMCD
 WHERE CMCD.CODE_GROUP_ID = #{CODE_GROUP_ID}
   AND CMCD.CODE = #{CODE}
   AND CMCD.DEL_YN = 'N'

   AND CMCD.CODE_ID != #{EXCLUDE_CODE_ID}

